// The chat's suggestions for . commands (chat_suggest.rs): a click on its list picks one.
fn sunset_chat_suggest_click(game: &mut crate::game::Game<'_>) -> std::ops::ControlFlow<()> {
    if ::sunset_core::lifecycle::RUNTIME.running() && crate::game::sunset_chat_suggest::click(game) {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// The chat's suggestions for . commands (chat_suggest.rs): Tab, and Up, Down and Escape while its list shows.
fn sunset_chat_suggest_key(game: &mut crate::game::Game<'_>, key: winit::keyboard::KeyCode) -> std::ops::ControlFlow<()> {
    if ::sunset_core::lifecycle::RUNTIME.running() && crate::game::sunset_chat_suggest::key(game, key) {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// The chat's suggestions for . commands (chat_suggest.rs): the wheel over its list scrolls the list, not the chat.
fn sunset_chat_suggest_scroll(game: &crate::game::Game<'_>, amount: f32) -> std::ops::ControlFlow<()> {
    if ::sunset_core::lifecycle::RUNTIME.running() && crate::game::sunset_chat_suggest::scroll(game, amount) {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// A chat line starting with `.` is a Sunset command, never sent.
fn sunset_chat(game: &mut crate::game::Game<'_>, message: &str) -> std::ops::ControlFlow<()> {
    if crate::game::sunset::chat(game, message) {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// F1 leaves the HUD shown while the menu is open: the menu is drawn with the HUD, and hidden it would still take the
// mouse and keys.
fn sunset_hide_hud() -> std::ops::ControlFlow<()> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if crate::game::sunset::gui_open() {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// The open click GUI goes over all the frame's HUD, after the chat, titles, tab list and toasts, and under its prompts.
fn sunset_gui_top(game: &crate::game::Game<'_>, batch: &mut horizon_client::hud::HudBatch) {
    if !::sunset_core::lifecycle::RUNTIME.running() { return; }

    crate::game::sunset::gui_top(game, batch);
}

// Streamer Mode: a centred layout (a title, the action bar, the boss bars) drawn with the names replaced.
fn sunset_streamer_centred(value: Vec<hud_layout::GuiDraw>, game: &Game<'_>) -> Vec<hud_layout::GuiDraw> {
    if !::sunset_core::lifecycle::RUNTIME.running() {
        return value;
    }
    crate::game::sunset_streamer::protect_draws(value, &game.gui.atlas.font, true)
}

// Anti Vanish keeps a watchlist per server, and Client Spoofer picks the brand for it: the address being joined.
fn sunset_vanish_connect(game: &Game<'_>, address: &str) {
    if !::sunset_core::lifecycle::RUNTIME.running() { return; }

    // Joining straight from the command line comes before Sunset's first tick read its settings.
    crate::game::sunset::ensure_loaded(game);
    crate::game::sunset_vanish::connecting(address);
    crate::game::sunset_meshcache_warm::reset();
    crate::game::sunset_server_scan::connecting(address);
    crate::game::sunset_sky::forget();
    crate::game::sunset_client_spoofer::connecting(address);
}

// Client Sort draws its three buttons instead of Horizon's sort button, and notes the slot under the pointer (Shift fill).
fn sunset_sort_draw(game: &crate::game::Game<'_>, batch: &mut horizon_client::hud::HudBatch, ox: f32, oy: f32) -> std::ops::ControlFlow<()> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    crate::game::sunset_extras::note_hover(game.slot_at(batch, game.cursor.0, game.cursor.1));
    if crate::game::sunset_extras::on() {
        crate::game::extras::sorting::sunset_sort_buttons::draw(game, batch, ox, oy);
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// A mouse press goes to the click GUI while it is open, before the game sees it; then to the Loadouts panel and
// Shulker Peek's view.
fn sunset_press(game: &mut crate::game::Game<'_>, button: winit::event::MouseButton) -> std::ops::ControlFlow<bool> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if crate::game::sunset::gui_open() {
        crate::game::sunset::gui_press(game, button);
        return std::ops::ControlFlow::Break(true);
    }
    if crate::game::sunset_loadouts::press(game, button == winit::event::MouseButton::Right) {
        return std::ops::ControlFlow::Break(true);
    }
    if crate::game::sunset_render::peek_press(game, button == winit::event::MouseButton::Middle) {
        return std::ops::ControlFlow::Break(true);
    }
    std::ops::ControlFlow::Continue(())
}

// A press on Client Sort's buttons, instead of Horizon's sort button.
fn sunset_sort_press(game: &mut crate::game::Game<'_>) -> std::ops::ControlFlow<bool> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if crate::game::sunset_extras::on() {
        return std::ops::ControlFlow::Break(crate::game::extras::sorting::sunset_sort_buttons::press(game));
    }
    std::ops::ControlFlow::Continue(())
}

// Client Sort: Horizon's sort, in Client Sort's order.
fn sunset_sort(game: &mut crate::game::Game<'_>, slots: &[usize]) -> std::ops::ControlFlow<()> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if crate::game::sunset_extras::sort(game, slots) {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// The HUD: ESP, tracers, name tags, then the watermark, module list and
// coordinates in their corners.
fn sunset_hud(
    game: &mut crate::game::Game<'_>,
    batch: &mut horizon_client::hud::HudBatch,
    corners: &mut horizon_client::extras_hud::Corners,
) {
    if !::sunset_core::lifecycle::RUNTIME.running() { return; }

    crate::game::sunset::hud(game, batch, corners);
}

// Mouse buttons while playing, as keys: binds on the side buttons and the wheel click.
fn sunset_mouse_key(game: &mut crate::game::Game<'_>, button: winit::event::MouseButton, pressed: bool) {
    let name = horizon_client::keybinds::mouse_name(button);
    crate::game::sunset::key(game, &name, pressed);
}

// Multitask: a left click while you use an item, which the game will drop, is counted for a hit.
fn sunset_multitask_click(game: &crate::game::Game<'_>, button: winit::event::MouseButton, pressed: bool) {
    if !::sunset_core::lifecycle::RUNTIME.running() { return; }

    crate::game::sunset_parity::clicked(game, button == winit::event::MouseButton::Left && pressed);
}

// Zoom: the mouse turns slower the further in the view is.
fn sunset_zoom_turn(game: &crate::game::Game<'_>) -> std::ops::ControlFlow<f64> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    match crate::game::sunset_render::zoom_turn(game) {
        Some(scale) => std::ops::ControlFlow::Break(scale),
        None => std::ops::ControlFlow::Continue(()),
    }
}

// Zoom: the field of view divided by the zoom the view is at.
fn sunset_zoom_fov(game: &crate::game::Game<'_>, fov: f32) -> std::ops::ControlFlow<f32> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    match crate::game::sunset_render::zoom_now(game) {
        Some(factor) => std::ops::ControlFlow::Break(fov / factor),
        None => std::ops::ControlFlow::Continue(()),
    }
}

// No Render's Hide hurt cam: no tilt of the view when you are hurt (the damage tilt's strength is 0).
fn sunset_hurt_cam(value: f64) -> f64 {
    if ::sunset_core::lifecycle::RUNTIME.running()
        && ::sunset_core::overlay::NO_HURT.load(std::sync::atomic::Ordering::Relaxed)
    {
        return 0.0;
    }
    value
}

// Hand View: the bare arm, moved, turned and sized, and lit at full brightness with No hand shadow (drawn again
// with the new pose and light, once).
fn sunset_arm_pose(this: &Game<'_>, left: bool, m: glam::Mat4, light: u32, partial: f32, out: &mut Vec<Vertex>) -> std::ops::ControlFlow<()> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    use crate::game::sunset_hand_view as view;
    if view::posing() {
        return std::ops::ControlFlow::Continue(());
    }
    let posed = view::posed(left, m);
    let lit = view::hand_light(light);
    if posed == m && lit == light {
        return std::ops::ControlFlow::Continue(());
    }
    view::set_posing(true);
    this.first_person_arm(left, posed, lit, partial, out);
    view::set_posing(false);
    std::ops::ControlFlow::Break(())
}

// Hit Through Walls: the mob under the crosshair is before the block you aim at.
fn sunset_wall_hit(game: &crate::game::Game<'_>, distance: f64) -> std::ops::ControlFlow<bool> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if crate::game::sunset_player::hit_through_walls(game, distance) {
        return std::ops::ControlFlow::Break(true);
    }
    std::ops::ControlFlow::Continue(())
}

// Hand View's Slow swing: your own swings last longer (the game's own duration otherwise, haste and fatigue too).
fn sunset_swing_hand(this: &mut Game<'_>, hand: Hand, animation: SwingAnimation) -> std::ops::ControlFlow<()> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    use crate::game::sunset_hand_view as view;
    if !view::SLOW_SWING.load(std::sync::atomic::Ordering::Relaxed) {
        return std::ops::ControlFlow::Continue(());
    }
    if this.swing.start_if_able(hand, animation, animation.duration.max(view::SLOW_SWING_TICKS)) {
        this.swings_started += 1;
    }
    std::ops::ControlFlow::Break(())
}

// Hand View's No equip drop: the hands stay up when the held item changes or the attack cooldown runs, and a new
// item shows at once.
fn sunset_equip_hold(value: [bool; 2], game: &mut Game<'_>, changed: [bool; 2]) -> [bool; 2] {
    if ::sunset_core::lifecycle::RUNTIME.running()
        && ::sunset_core::hand_view::NO_EQUIP_DROP.load(std::sync::atomic::Ordering::Relaxed)
    {
        let h = &mut game.heights;
        (h.main, h.old_main, h.off, h.old_off) = (1.0, 1.0, 1.0, 1.0);
        return changed;
    }
    value
}

// Hand View's 1.8 Animations: the hand does not dip after a hit (1.8 had no cooldown), as Horizon's own Combat feel
// Legacy raises it, but still drops and rises for a new item.
fn sunset_equip_legacy(value: bool) -> bool {
    value
        || (::sunset_core::lifecycle::RUNTIME.running()
            && ::sunset_core::hand_view::LEGACY.load(std::sync::atomic::Ordering::Relaxed))
}

fn sunset_gui_move_shift(game: &crate::game::Game<'_>, value: bool) -> bool {
    if !::sunset_core::lifecycle::RUNTIME.running() { return value; }

    value && !crate::game::sunset_gui_move::suppress_shift(game)
}

// Item Durability: the number on the item's icon, after the icon.
fn sunset_item_durability(
    game: &crate::game::Game<'_>,
    batch: &mut HudBatch,
    stack: &ItemStack,
    x: f32,
    y: f32,
) -> std::ops::ControlFlow<()> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    crate::game::sunset_hud_bars::item_model(game, batch, stack, x, y)
}

// Hand View: an item held in first person, moved, turned and sized, swung (and a sword blocked) as its Animations say,
// 1.9+ or 1.8, and lit at full brightness with No hand shadow.
fn sunset_hand_item(this: &Game<'_>, state: &ItemRenderState, pose: glam::Mat4, light: u32, out: &mut Vec<Vertex>) -> std::ops::ControlFlow<()> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    use crate::game::sunset_hand_view as view;
    let left = match state.display {
        DisplayContext::FirstPersonLeftHand => true,
        DisplayContext::FirstPersonRightHand => false,
        _ => return std::ops::ControlFlow::Continue(()),
    };
    // Swing animation: only an item swung as the game swings it (not a crossbow, a spear, a stab or a spin, nor one in
    // use but a blocking sword: `plain` below).
    let hand = if left == this.settings.main_hand_left { horizon_client::first_person::Hand::Main } else { horizon_client::first_person::Hand::Off };
    let stack = if hand == horizon_client::first_person::Hand::Main { this.held() } else { this.offhand.as_ref() };
    let swung = !this.player.as_ref().is_some_and(|p| p.auto_spin_attack_ticks > 0)
        && !this.swing.current.is_some_and(|c| c.animation.kind == 2)
        && stack.is_none_or(|s| &*s.item != "minecraft:crossbow" && horizon_client::spear::Kinetic::of(&s.item).is_none());
    let attack = if this.swing.attack_hand() == hand { this.swing.animation(this.clock.camera_fraction() as f32) } else { 0.0 };
    let sword = stack.is_some_and(|s| this.res.items().item_tags.get("minecraft:swords").is_some_and(|t| t.contains(&*s.item)));
    let game_pose = pose;
    let main = hand == horizon_client::first_person::Hand::Main;
    // The main hand's sword in a real use: a 1.8 server behind ViaVersion makes its swords blocking items, so right click
    // (or Kill Aura's AutoBlock) starts a use and the game turns the sword across the body, its own block. Where the
    // block is Hand View's to show, that is the same block as before the use began and between two hits, shown the
    // same way: the sword jumped between the game's block and Hand View's each time a use started or stopped.
    let used_block = main && sword && view::OWN_BLOCK.load(std::sync::atomic::Ordering::Relaxed)
        && this.using.is_some_and(|(slot, _)| slot != crate::game::sunset_util::OFFHAND);
    let plain = swung && (this.using.is_none() || used_block);
    // A flat item with the game's own display (a resource pack's own keeps the game's pose), and whether Horizon's
    // Combat feel Legacy already drew it the 1.8.9 way (blocking while use is held with a sword, as it does).
    let flat = !state.layers.is_empty()
        && state.layers.iter().all(|l| horizon_client::first_person::is_modern_flat_display(&l.matrix, left));
    let native = this.settings.extras.pvp.combat.legacy && flat;
    let native_block = native && main && this.right && this.screen == super::Screen::Playing
        && stack.is_some_and(|s| s.item.ends_with("_sword"));
    // A blocking sword (Kill Aura's Legacy AutoBlock, Block on right click, or Horizon's own block): the main hand's. It
    // goes into the block at once, as 1.8's did (a blend between the two poses turned the sword a long way round).
    let block = main && sword && (view::SWORD_BLOCK.load(std::sync::atomic::Ordering::Relaxed) || native_block || used_block);
    let time = (this.ticks as f64 + this.clock.camera_fraction()) as f32 / 20.0;
    // The swing Hand View's animations play: its own clock for the main hand (a swing plays out before the next), the
    // game's for the other.
    let s = if main && this.swing.attack_hand() == hand {
        view::swing_clock(this.swings_started as u64, this.swing.current.map_or(6, |c| c.duration_ticks), time)
    } else {
        attack
    };
    let how = match (native && !left, used_block) {
        (true, _) => view::Drawn::Legacy { block: native_block },
        (false, true) => view::Drawn::Block,
        (false, false) => view::Drawn::Modern,
    };
    // Combat feel Legacy draws a sword in use at rest (no swing) unless right click holds it in its block.
    let drawn_attack = if used_block && !native_block { 0.0 } else { attack };
    // The pose blocking or not: 1.8's for a flat item in the right main hand (hand_view_flags), else the 1.9+ swing
    // in the game's swing's place. Horizon's 1.8.9 pose of a left hand is left as it is.
    let shape = |block: bool| -> glam::Mat4 {
        let legacy = (plain && main && !left && flat)
            .then(|| view::legacy_pose(pose, drawn_attack, s, block, time, how, view::view_of(left)))
            .flatten();
        if let Some(legacy) = legacy {
            return legacy;
        }
        let swapped = match view::swing_swap(left, attack, s, sword, block, used_block).filter(|_| plain && !native) {
            Some(swap) => pose * swap,
            None => pose,
        };
        view::posed(left, swapped)
    };
    let posed = shape(block);
    let lit = view::hand_light(light);
    // Nothing changed from the game's own pose and light: the game draws it.
    if posed == game_pose && lit == light {
        return std::ops::ControlFlow::Continue(());
    }
    this.submit_item_lit(state, posed, lit, diffuse_lights(this.dim == Dim::Nether), out);
    std::ops::ControlFlow::Break(())
}

// Velocity: an explosion's push on the player, noted before the game adds it; Wind Jump times its jump by the blast.
fn sunset_explode(game: &mut crate::game::Game<'_>, p: &play::Explode) {
    if !::sunset_core::lifecycle::RUNTIME.running() { return; }

    crate::game::sunset_duel::blast(game, p.knockback);
    crate::game::sunset::explosion_push(game, p.knockback);
}

// Mount HUD: the mount's hearts above the food row.
fn sunset_mount_hearts(
    w: i32,
    h: i32,
    hearts: i32,
    health: f32,
    operation: impl FnOnce(i32, i32, i32, f32) -> Vec<horizon_client::hud_layout::GuiDraw>,
) -> Vec<horizon_client::hud_layout::GuiDraw> {
    let draws = operation(w, h, hearts, health);
    if !::sunset_core::lifecycle::RUNTIME.running() { return draws; }

    crate::game::sunset_hunger::raise(draws)
}

// Streamer Mode: a name tag over a player or a named mob drawn with the names replaced (cached as drawn).
fn sunset_streamer_name_tag(
    this: &mut NameTagLayouts,
    batch: &mut HudBatch,
    atlas: &HudAtlas,
    text: &Text,
    y: f32,
    alpha: u32,
    background: bool,
) -> ::core::ops::ControlFlow<usize> {
    if !::sunset_core::lifecycle::RUNTIME.running() {
        return ::core::ops::ControlFlow::Continue(());
    }
    match crate::game::sunset_streamer::protect(text) {
        Some(shown) => ::core::ops::ControlFlow::Break(crate::game::sunset_streamer::guarded(|| {
            this.name_tag(batch, atlas, &shown, y, alpha, background)
        })),
        None => ::core::ops::ControlFlow::Continue(()),
    }
}

// Clear Water's lighter tint: each biome's water colour, as a mod's biome_colors answer gives it.
fn sunset_water_tint(colors: &mut BiomeColors) {
    if ::sunset_core::lifecycle::RUNTIME.running() {
        colors.water = ::sunset_core::water::lighter(colors.water);
    }
}

// Sunset's block overlay owns the frame: the game's own outline of the block looked at is left out (as a mod's
// block_highlight answer does).
fn sunset_block_overlay_draw(canceled: &mut bool) {
    if ::sunset_core::lifecycle::RUNTIME.running() && ::sunset_core::block_overlay::active() {
        *canceled = true;
    }
}

// The wheel scrolls a click GUI panel, and stays off the hotbar while it is open; held Zoom and a flying Freecam
// take it too (zoom level, camera speed).
fn sunset_wheel(game: &crate::game::Game<'_>, accumulated: [i32; 2], claimed: &mut bool) {
    let steps = accumulated[1] as f32;
    if !::sunset_core::lifecycle::RUNTIME.running() { return; }

    if crate::game::sunset::gui_open() {
        crate::game::sunset::gui_wheel(game, steps);
        *claimed = true;
    } else if crate::game::sunset_render::camera_wheel(game, steps) {
        *claimed = true;
    }
}

// Sunset's text, in Sunset's font. Sunset gives its colours as 0xRRGGBB (alpha 0 is opaque, as the API it was written
// for took them); the game's native_text now reads that as fully transparent and draws nothing, so Sunset's text is
// drawn here in either font.
fn sunset_text_hook(game: &Game<'_>, batch: &mut HudBatch, text: &str, at: [f32; 2], argb: u32, shadow: bool) -> std::ops::ControlFlow<()> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    crate::game::sunset_font::draw(game, batch, text, at, argb, shadow);
    std::ops::ControlFlow::Break(())
}

// After each tick: the modules' work.
fn sunset_tick(game: &mut crate::game::Game<'_>) {
    crate::game::sunset::post_tick(game);
    crate::game::remote::sunset_tab_marks::apply(game, ::sunset_core::lifecycle::RUNTIME.running());
    crate::game::sunset_client_spoofer::pack_tick(game);
}

fn sunset_text_width_hook(game: &Game<'_>, text: &str) -> std::ops::ControlFlow<f32> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    crate::game::sunset_font::ensure(&game.gui.atlas.font);
    if !crate::game::sunset_font::enabled() {
        return std::ops::ControlFlow::Continue(());
    }
    std::ops::ControlFlow::Break(crate::game::sunset_font::width(&game.gui.atlas.font, text))
}

// Before drawing: the time and weather asked for, as a module may have turned on or off in a tick; also on the title
// screen, where nothing is left of the last world. RF Click learns whether you type; .goto stops or reports; Offhand's
// Auto Totem clicks, between ticks as a screen's clicks are; plugins hear of joins and disconnects; Streamer Mode's
// names to hide (on the title screen too); the chat's suggestions for . commands.
fn sunset_sky_frame(game: &mut crate::game::Game<'_>) {
    crate::game::sunset_packets::register();
    crate::game::sunset_streamer::register();
    crate::game::sunset_atmosphere_renderer::register();
    crate::game::sunset_render::register();
    crate::game::sunset::finish_shutdown(game);
    crate::game::sunset_baritone::maintain(game);
    if !::sunset_core::lifecycle::RUNTIME.running() { return; }

    crate::game::sunset_gui_move::frame(game);
    crate::game::sunset_antibot::frame(game);
    crate::game::sunset_autoclicker::frame(game);
    crate::game::agent::sunset_goto::frame(game);
    crate::game::sunset_sky::shown(game);
    crate::game::sunset_hands::frame(game);
    crate::game::sunset_combat_inventory::frame(game);
    crate::game::sunset_api::frame(game);
    if !crate::game::sunset::running() { return; }
    crate::game::sunset_streamer_mode::frame(game);
    crate::game::sunset_chat_suggest::frame(game);
}

// Sunset's page in Options > Mods: the menu's buttons as the page's rows (its Config button shows while it has rows).
fn sunset_settings(value: Vec<NativeSetting>, game: &Game<'_>, mod_id: &str) -> Vec<NativeSetting> {
    if mod_id != crate::game::sunset::ID {
        return value;
    }
    crate::game::sunset_runtime_menu::page_rows(game)
        .into_iter()
        .enumerate()
        .map(|(i, (label, on))| NativeSetting {
            key: format!("menu.{i}"),
            label,
            tooltip: None,
            value: NativeSettingValue::Toggle(on),
        })
        .collect()
}

// A row of Sunset's page pressed.
fn sunset_click(game: &mut Game<'_>, i: usize, j: usize) -> ::core::ops::ControlFlow<()> {
    if crate::game::sunset_runtime_menu::mod_index(game) != Some(i) {
        return ::core::ops::ControlFlow::Continue(());
    }
    crate::game::sunset_runtime_menu::page_pressed(game, j);
    ::core::ops::ControlFlow::Break(())
}

fn sunset_gui_move_incoming(
    game: &mut Game<'_>,
    packet: &horizon_protocol::packets::play::Clientbound,
) {
    if !::sunset_core::lifecycle::RUNTIME.running() { return; }

    crate::game::sunset_gui_move::incoming_before(game, packet);
}

fn sunset_seedcracker_incoming(
    _game: &mut Game<'_>,
    packet: &horizon_protocol::packets::play::Clientbound,
) {
    if crate::game::sunset_seedcracker::incoming_before(packet) {
