// Criticals: your own hit on a mob waits for the hop or the fall that makes it critical. While a combat macro runs,
// clicks do nothing, nor those No Interact stops (its lists, Hit fix, Sword on shield, Hit select); Aim Assist's Silent
// aim and Hit flick take a miss or a hit next, then No miss delay drops a swing at nothing; Packet Mine takes a click
// on a block; Friend Guard and Auto Spear's Reach poke and Extended reach see the click first, then Auto Mace takes
// the mace for it; Displace holds a hit back a tick for its knockback's yaw. A click on a block that gets through starts Vein Miner's watch.
fn sunset_crit_click(game: &mut crate::game::Game<'_>) -> std::ops::ControlFlow<bool> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if crate::game::sunset_combat_macros::active()
        || crate::game::sunset_parity::hit_blocked(game)
        || crate::game::sunset_click_fix::hit_blocked(game)
        || crate::game::sunset_click_fix::hit_select(game)
    {
        return std::ops::ControlFlow::Break(false);
    }
    if let Some(instant) = crate::game::sunset_click_fix::aim_click(game) {
        return std::ops::ControlFlow::Break(instant);
    }
    if crate::game::sunset_click_fix::miss_blocked(game) {
        return std::ops::ControlFlow::Break(false);
    }
    if crate::game::sunset_packet_mine::click(game, true) {
        return std::ops::ControlFlow::Break(false);
    }
    if let Some(instant) = crate::game::sunset_melee::before_click(game) {
        return std::ops::ControlFlow::Break(instant);
    }
    crate::game::sunset_auto_mace::before_click(game);
    if let Some(instant) = crate::game::sunset_aura_knockback::displace_click(game) {
        return std::ops::ControlFlow::Break(instant);
    }
    match crate::game::sunset::crit_click(game) {
        Some(instant) => std::ops::ControlFlow::Break(instant),
        None => {
            crate::game::sunset_vein_miner::clicked(game);
            std::ops::ControlFlow::Continue(())
        }
    }
}

