// No Slow: the item-use slowdown left out.
fn sunset_noslow_hook(input: [f32; 2], item_use: Option<f32>, sneaking: Option<f32>) -> std::ops::ControlFlow<[f32; 2]> {
    use std::sync::atomic::Ordering::Relaxed;
    if item_use.is_some() && ::sunset_core::input::NO_SLOW.load(Relaxed) {
        // The slowdown by No Slow's factor instead of the game's: the input without it, scaled (modify_input with
        // Some(factor) would come back into this hook for ever).
        let factor = f32::from_bits(::sunset_core::input::NO_SLOW_FACTOR.load(Relaxed)).clamp(0.2, 1.0);
        let [x, z] = modify_input(input, None, sneaking);
        return std::ops::ControlFlow::Break([x * factor, z * factor]);
    }
    std::ops::ControlFlow::Continue(())
}

// Timer: the frame's elapsed time, scaled.
fn sunset_timer_hook(this: &mut FixedStep, elapsed: std::time::Duration, target_millis: f32) -> std::ops::ControlFlow<u32> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    use std::sync::atomic::Ordering::Relaxed;
    let m = f32::from_bits(::sunset_core::timer::MULT.load(Relaxed));
    if m == 1.0 || ::sunset_core::timer::BUSY.swap(true, Relaxed) {
        return std::ops::ControlFlow::Continue(());
    }
    let ticks = this.advance(elapsed.mul_f32(m), target_millis);
    ::sunset_core::timer::BUSY.store(false, Relaxed);
    std::ops::ControlFlow::Break(ticks)
}

