fn sunset_server_scan_config_channel(
    payload: &horizon_protocol::packets::configuration::CustomPayload,
) {
    if !::sunset_core::lifecycle::RUNTIME.running() { return; }

    if let Some(seen) = ::sunset_core::bridge::CONFIG_PAYLOAD.get() {
        seen(payload as *const horizon_protocol::packets::configuration::CustomPayload as *mut u8);
    }
}

// Flight: the next move packet carries the position when the anti kick asks for it. A move packet whose ground Sunset
// changed: the game compares with the ground the server was told.
fn sunset_sync(this: &mut PositionSender) {
    if !::sunset_core::lifecycle::RUNTIME.running() { return; }

    if ::sunset_core::sync::take() {
        this.reminder = 20;
    }
    if let Some(told) = ::sunset_core::sync::take_ground() {
        this.on_ground = told;
    }
}

// Debug Report's chat log: each line as it comes into the chat.
fn sunset_debug_chat(content: &crate::text::Text, source: crate::chat::ChatSource) {
    // Names the crate root's re-export the game's copy of Chat::add reaches through its module's imports.
    #[allow(unused_imports)]
    use crate::command as _;
    if !::sunset_core::lifecycle::RUNTIME.running() { return; }

    ::sunset_core::chat_log::added(&content.strip_legacy().plain(), source as u8);
}

// Streamer Mode: a line coming into the chat, its names replaced (after Debug Report's log and plugins' on_chat have
// it as it came).
fn sunset_streamer_chat(value: Text) -> Text {
    let mut value = value;
    if ::sunset_core::lifecycle::RUNTIME.running()
        && let Some(protect) = ::sunset_core::bridge::STREAMER_TEXT.get()
    {
        protect(&mut value as *mut Text as ::sunset_core::bridge::Ptr);
    }
    value
}

// No Render: water, lava and powder snow fog turned into plain air.
fn sunset_fog_hook(world: &World, facts: &BlockFacts, camera: [f64; 3], near: &NearPlane, seen: &dyn Fn(BlockStateId, [i32; 3]) -> BlockStateId) -> std::ops::ControlFlow<FogType> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    use std::sync::atomic::Ordering::Relaxed;
    let (water, lava) = (::sunset_core::fog::NO_WATER.load(Relaxed), ::sunset_core::fog::NO_LAVA.load(Relaxed));
    if !(water || lava) || ::sunset_core::fog::busy() {
        return std::ops::ControlFlow::Continue(());
    }
    ::sunset_core::fog::set_busy(true);
    let found = fog_type(world, facts, camera, near, seen);
    ::sunset_core::fog::set_busy(false);
    std::ops::ControlFlow::Break(match found {
        FogType::Water if water => FogType::Atmospheric,
        FogType::Lava | FogType::PowderSnow if lava => FogType::Atmospheric,
        other => other,
    })
}

// Sunset's glyphs: the coverage goes in the alpha over white, which an ordinary blend wants, instead of grey in
// every channel (which blends as the coverage squared and thins every edge), and a touch of weight is added.
// Only grey texels are changed, so the bitmap fonts' white and transparent ones stay as they are.
fn sunset_patches(this: &Font) -> std::ops::ControlFlow<Vec<Patch>> {
    // Names the crate root's re-exports the game's copy of the font module reaches through its imports.
    #[allow(unused_imports)]
    use crate::{resource_source as _, zip as _};
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if ::sunset_core::font::STYLE.load(std::sync::atomic::Ordering::Relaxed) == 0 {
        return std::ops::ControlFlow::Continue(());
    }
    let mut patches = std::mem::take(&mut this.cache.borrow_mut().region.pending);
    for patch in &mut patches {
        for px in patch.rgba.chunks_exact_mut(4) {
            if px[0] == px[3] && px[1] == px[3] && px[2] == px[3] {
                let coverage = f32::from(px[3]) / 255.0;
                px.copy_from_slice(&[255, 255, 255, (coverage.powf(0.8) * 255.0).round() as u8]);
            }
        }
    }
    std::ops::ControlFlow::Break(patches)
}

// The procedural field owns stars only after a custom sky pipeline succeeded.
// This restores vanilla stars automatically on every disabled or unsupported frame.
fn sunset_atmosphere_stars() -> std::ops::ControlFlow<()> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if ::sunset_core::atmosphere::owns_sky() {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// Restore and release cached device objects before Horizon replaces its renderer.
fn sunset_atmosphere_release(renderer: &mut Renderer) {
    if let Some(release) = ::sunset_core::bridge::RELEASE_SURFACE.get() {
        release(renderer as *mut Renderer as *mut u8);
    }
}

// No Render: the blur behind the pause menu and other screens is left out with the dark sheet.
fn sunset_menu_blur() -> std::ops::ControlFlow<()> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if ::sunset_core::overlay::NO_MENU.load(std::sync::atomic::Ordering::Relaxed) {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// No Render: a hidden particle is not made at all.
fn sunset_particle_add(options: &ParticleOptions) -> std::ops::ControlFlow<()> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if ::sunset_core::particles::any() && ::sunset_core::particles::hidden(options.ty.name()) {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// No Render: a hidden particle the game makes outside the options path (block crumbs and breaking, cracks, the
// warden's digging, the renderer's own) is never added.
fn sunset_particle_push(particle: &Particle) -> std::ops::ControlFlow<()> {
    if ::sunset_core::lifecycle::RUNTIME.running()
        && ::sunset_core::particles::any()
        && ::sunset_core::particles::hidden(particle.ty.name())
    {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}

// No Render: the screen overlays the player chose to hide are left out.
fn sunset_overlay_hook(this: &ScreenEffects, input: &ScreenInputs<'_>) -> std::ops::ControlFlow<Vec<ScreenQuad>> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    use std::sync::atomic::Ordering::Relaxed;
    let (fire, liquid, wall, gui) = (
        ::sunset_core::overlay::NO_FIRE.load(Relaxed),
        ::sunset_core::overlay::NO_LIQUID.load(Relaxed),
        ::sunset_core::overlay::NO_WALL.load(Relaxed),
        ::sunset_core::overlay::NO_GUI.load(Relaxed),
    );
    if !(fire || liquid || wall || gui) || ::sunset_core::overlay::busy() {
        return std::ops::ControlFlow::Continue(());
    }
    ::sunset_core::overlay::set_busy(true);
    let none: &[GuiDraw] = &[];
    let changed = ScreenInputs {
        sprites: input.sprites,
        flags: input.flags,
        aspect: input.aspect,
        partial: input.partial,
        block_overlay: if wall { None } else { input.block_overlay.clone() },
        water: if liquid { None } else { input.water },
        on_fire: input.on_fire && !fire,
        fire_lower: input.fire_lower,
        gui_overlays: if gui { none } else { input.gui_overlays },
        custom: input.custom,
    };
    let quads = this.build(&changed);
    ::sunset_core::overlay::set_busy(false);
    std::ops::ControlFlow::Break(quads)
}

// No Render: the shade behind the pause menu in a world is left out.
fn sunset_pause_dark(in_world: bool) -> std::ops::ControlFlow<()> {
    if !::sunset_core::lifecycle::RUNTIME.running() { return std::ops::ControlFlow::Continue(()); }

    if in_world && ::sunset_core::overlay::NO_MENU.load(std::sync::atomic::Ordering::Relaxed) {
        return std::ops::ControlFlow::Break(());
    }
    std::ops::ControlFlow::Continue(())
}
